# Workspace draft editor

`createWorkspace` drives a document editor and its save badge. The workspace store
holds draft text across navigation and closed editor views. Returning to a document
restores the user's last edit. Save integrations receive committed records and may
select another document synchronously. Later navigation means the navigation request that starts later takes precedence, even if an earlier request returns afterward. For example, if open(B) starts and saving the departed A invokes a callback that calls open(C), C remains selected after the callback and the outer open(B) return. If that callback calls close() instead, the editor remains closed after the outer open(B) returns. These are navigation results, independent of when the departed document's save occurs.
When close/open returns, the departed document's last accepted edit is available
through the store, even if the next view selects a different document.

`createSearchPreview` is an adjacent transient search panel. It publishes after a
40 ms quiet interval; hiding it discards an unpublished query. It can be reused.

The public methods are synchronous. Output render functions observe state; navigation
comes through the workspace API, including its `onSaved` integration. `store` provides
`read`, `write` and `subscribe`; `timers` provides `schedule(callback, delay)` and
`cancel(handle)`. Production timers use the browser's timers. Keep these interfaces.
// A synchronous workspace store, independent of whether an editor is visible.
// Notifications run inline after the record is written. Subscribers may detach
// or subscribe while a notification is being delivered.
export function createDraftStore(initial = {}) {
  const records = new Map(Object.entries(initial));
  const listeners = new Set();
  let revision = 0;
  return {
    read(id) { return records.get(id) ?? ""; },
    write(id, text) {
      records.set(id, text);
      const event = { id, text, revision: ++revision };
      for (const listener of [...listeners]) {
        if (listeners.has(listener)) listener(event);
      }
      return event;
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}
import { attachSaveStatus } from "./save-status.js";

export function createDraftEditor({ store, timers, renderDocument, renderStatus }) {
  let current = null;
  function close() {
    const leaving = current;
    current = null;
    if (leaving) leaving.stop();
    renderDocument(null);
  }
  return {
    open(id) {
      close();
      current = { id, stop: attachSaveStatus(store, id, renderStatus) };
      renderDocument({ id, text: store.read(id) });
    },
    edit(text) {
      if (current) store.write(current.id, text);
    },
    close,
  };
}
// A mounted document's save badge. A close/open request retires the departing
// badge immediately: it must produce no further output, including during that
// navigation call. Saving the document itself is a separate workspace concern.
export function attachSaveStatus(store, id, renderStatus) {
  return store.subscribe(event => {
    if (event.id === id) renderStatus(event);
  });
}
import { createTrailingTask } from "./trailing-task.js";

export function createSearchPreview({ timers, publish }) {
  const task = createTrailingTask(query => publish({ query }), 40, timers);
  return {
    query(text) { task.push(text); },
    // A hidden preview has no use for a pending query; reopen starts fresh.
    hide() { task.cancel(); },
  };
}
export const browserTimers = {
  schedule(callback, delay) { return setTimeout(callback, delay); },
  cancel(handle) { clearTimeout(handle); },
};
import { browserTimers } from "./timers.js";

// Coalesce calls until a quiet interval. cancel discards work; flush runs it now.
// Retire the old batch before invoking work, which can enqueue another batch.
export function createTrailingTask(work, delay, timers = browserTimers) {
  let handle = null;
  let pending = null;
  function flush() {
    if (handle !== null) timers.cancel(handle);
    handle = null;
    const args = pending;
    pending = null;
    if (args !== null) work(...args);
  }
  return {
    push(...args) {
      if (handle !== null) timers.cancel(handle);
      pending = args;
      handle = timers.schedule(flush, delay);
    },
    flush,
    cancel() {
      if (handle !== null) timers.cancel(handle);
      handle = null;
      pending = null;
    },
  };
}
import { createDraftEditor } from "./editor.js";

// Autosave integrations can select a different document from inside onSaved.
// One navigation object and store are reused across close/open cycles, including
// returning to the same document. renderDocument/renderStatus are output sinks.
export function createWorkspace({ store, timers, renderDocument, renderStatus, onSaved = () => {} }) {
  const stop = store.subscribe(event => onSaved(event, navigation));
  const editor = createDraftEditor({ store, timers, renderDocument, renderStatus });
  const navigation = {
    open(id) { editor.open(id); },
    edit(text) { editor.edit(text); },
    close() { editor.close(); },
  };
  return { ...navigation, dispose() { stop(); editor.close(); } };
}
